def buildElement(value, fontWeight, foreColor, bgColor):
	style = {}
	if fontWeight is not None:	style.update({"fontWeight": fontWeight})		
	if foreColor is not None: style.update({"color": foreColor})
	if bgColor is not None: 	style.update({'backgroundColor': bgColor, 'borderColor': bgColor, 'borderRadius': '4px', 'margin': '3px'})	
	return {'value': value, 'style':style}

if value.rowCount > 1000: return value
data = system.kanoa.utilities.convertDatasetToJSON(value)
for row in data:
	row['chkShtStateName'] = buildElement(row['chkShtStateName'], None, '--kcGray-0', row['chkShtStateColor'])

return data

