system.perspective.print("itemSelected() msg rcvd by chkSchedule with %s"%payload)

items = []
itemClasses = []

for entry in payload['selection']:
	if entry['value']['itemId']: items.append({'itemPath':entry['value']['path'], 'itemId': entry['value']['itemId']})
	else: itemClasses.append({'itemClassPath':entry['value']['path'], 'itemClassId':system.kanoa.utilities.getFieldValue('itemClassId', system.kanoa.item.getItemClasses({'itemClassPath' :entry['value']['path']}))})

self.view.custom.filters.items = items
self.view.custom.filters.itemClasses = itemClasses

return
